public int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index < headerPart.length() && headerPart.charAt(index) != '\r' && headerPart.charAt(index) != '\n') {
        index++;
    }
    if (index == headerPart.length()) {
        throw new IllegalArgumentException("Invalid header format: missing end of line");
    }
    if (headerPart.charAt(index) == '\r' && ++index == headerPart.length()) {
        throw new IllegalArgumentException("Invalid header format: missing line feed after carriage return");
    }
    return index;
}

