public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Check if the input graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Input graph cannot be null");
    }

    // Create an empty mapping
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>();

    // Loop through the vertices and edges of the graph
    for (Vertex<V> vertex : graph.vertices) {
        for (Edge<E> edge : vertex.edges) {
            // If the vertex and edge are not in the mapping, add them
            if (!mapping.containsKey(vertex) && !mapping.containsKey(edge)) {
                mapping.put(vertex, edge);
            }
        }
    }

    // Return the mapping
    return mapping;
}

