@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // check if the target graph is null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // check if the result map is null or empty
    if (resultMap == null || resultMap.isEmpty()) {
        throw new IllegalArgumentException("Result map cannot be null or empty");
    }

    // create a new bipartite graph
    Graph<V, E> bipartiteGraph = new BipartiteGraph<>(target.getVertexCount());

    // add all vertices to the bipartite graph
    for (V vertex : resultMap.keySet()) {
        bipartiteGraph.addVertex(vertex);
    }

    // add all edges to the bipartite graph
    for (V vertex1 : resultMap.keySet()) {
        for (V vertex2 : resultMap.keySet()) {
            if (vertex1 != vertex2 && resultMap.get(vertex1).equals(vertex2)) {
                bipartiteGraph.addEdge(vertex1, vertex2);
            }
        }
    }

    // set the graph to the target graph
    target.setGraph(bipartiteGraph);
}

