    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema is null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer is null");
    }

    int size = schema.getSerializedSize(message);
    // Write the size delimited
    out.write(size);
    // Write the message
    schema.writeTo(buffer, message);
    // Flush the buffer
    buffer.flush();
    return size;
}

