public int addType(final String value) {
    // Check if the type table already contains a similar type
    for (int i = 0; i < typeTable.size(); i++) {
        if (typeTable.get(i).getValue().equals(value)) {
            // If it does, return its index
            return i;
        }
    }

    // If the type table doesn't contain a similar type, add a new type
    TypeSymbol newType = new TypeSymbol(value);
    typeTable.add(newType);
    return typeTable.size() - 1;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArgs = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            if (typeArgument instanceof Class) {
                resolvedArgs[i] = (Class<?>) typeArgument;
            } else {
                resolvedArgs[i] = null;
            }
        }
        return resolvedArgs;
    } else {
        return null;
    }
}

@Override
public void accept(final METRICS data) {
    // Check if the cache contains the data
    if (cache.containsKey(data.getLogicalName())) {
        // If it does, retrieve the existing value and merge with the new data
        METRICS existingData = cache.get(data.getLogicalName());
        existingData.setNumClicks(existingData.getNumClicks() + data.getNumClicks());
        existingData.setNumImpressions(existingData.getNumImpressions() + data.getNumImpressions());
        existingData.setAvgClickPosition(Math.max(existingData.getAvgClickPosition(), data.getAvgClickPosition()));
        existingData.setAvgImpressionPosition(Math.max(existingData.getAvgImpressionPosition(), data.getAvgImpressionPosition()));
    } else {
        // If it doesn't, add the data to the cache
        cache.put(data.getLogicalName(), data);
    }
}

