public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("Time bucket must be positive");
    }
    // Get the year, month, and day from the time bucket
    int year = getYear(timeBucket);
    int month = getMonth(timeBucket);
    int day = getDay(timeBucket);

    // Calculate the new day
    int newDay = Math.floorMod(day - 1, dayStep) + 1;

    // Calculate the new time bucket
    long newTimeBucket = Long.valueOf(year, month, newDay);

    return newTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Check if the input is null or empty
    if (str == null || index > str.length() || len <= 0) {
        return 0;
    }

    // Check if the string is already encoded in UTF-8
    if (str.isUTF8()) {
        return len;
    }

    // Convert the string to UTF-8
    CharBuffer buffer = CharBuffer.wrap(str);
    buffer.position(index);
    buffer.limit(index + len);
    String utf8String = new String(buffer.array(), "UTF-8");

    // Calculate the size of the UTF-8 string
    int size = 0;
    for (int i = 0; i < len; i++) {
        // Get the code point at the current position
        int codePoint = str.codePointAt(i);
        // Determine the number of bytes needed to encode the code point
        int numBytes;
        if (codePoint < 0x0080) {
            numBytes = 1;
        } else if (codePoint < 0x0800) {
            numBytes = 2;
        } else {
            numBytes = 3;
        }
        // Add the number of bytes to the total size
        size += numBytes;
    }

    return size;
}

