public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        int paddingLength = Math.max(0, byteLength - byteArrayValue.length + byteOffset);
        byte[] padding = new byte[paddingLength];
        this.write(padding, 0, paddingLength);
        return this;
    }

    if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid byteArrayValue offset or length");
    }

    this.write(byteArrayValue, byteOffset, byteLength);
    return this;
}

