public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (true) {
        int b = in.read();
        if (b == -1) {
            throw new EOFException("End of stream reached while trying to read raw varint.");
        }
        result |= ((long) (b & 0x7F)) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
    }
    return result;
}

