private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

    // Split the descriptor into tokens
    String[] tokens = descriptor.split(" ");
    if (tokens.length == 0) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

    // Pop the top frame
    String type = tokens[0];
    if (type.equals("(")) {
        // The descriptor is a method descriptor, pop the argument types
        for (int i = 1; i < tokens.length; i++) {
            if (tokens[i].equals(")")) {
                break;
            }
            pop(tokens[i]);
        }
    } else {
        // The descriptor is a type descriptor, pop the type
        pop(type);
    }
}

