        throw new IllegalArgumentException("Box width cannot be 0");
    }

    double xCenter = box.getCenterX();
    double yCenter = box.getCenterY();

    Box2D box1 = new Box2D(xCenter - width / 2, yCenter, xCenter, yCenter);
