public static int writeTo(final DataOutputStream out, final LinkedBuffer node) throws IOException {

// Buffer to hold temporary data
byte[] buffer = new byte[1024];
int totalSize = 0;

// Check if node is null
if ( node == null) {
throw new IllegalArgumentException("Node cannot be null");
}

// Write the data from each node in the linked buffer
LinkedBuffer currentNode = node;
while (currentNode != null) {

// Read the data into the buffer
int numBytesRead = currentNode.data.read(buffer, 0, 1024);

// Write the buffer to the output stream
if (numBytesRead > 0) {
out.write(buffer, 0, numBytesRead);
totalSize += numBytesRead;
} else {
break;
}

// Move to the next node
currentNode = currentNode.next;
}

return totalSize;

}

