private void putAbstractTypes(final int start,final int end){
    // Handle null or empty frames
    if (currentFrame == null || currentFrame.size() == 0) {
        return;
    }

    // Bounds check for start and end indices
    if (start < 0 || start > currentFrame.size() - 1 || end < 1 || end > currentFrame.size()) {
        throw new IndexOutOfBoundsException("Invalid indices for currentFrame");
    }

    // Validate types
    for (int i = start; i < end; i++) {
        if (currentFrame.get(i) == null) {
            throw new IllegalArgumentException("Null type at index " + i);
        }
        if (currentFrame.get(i).getSort() != Type.Sort.ABSTRACT_TYPE) {
            throw new IllegalArgumentException("Invalid type at index " + i);
        }
    }

    // Convert and write types to target
    for (int i = start; i < end; i++) {
        Type type = currentFrame.get(i).getType();
        if (type.equals(Type.Kind.CLASS)) {
            putClass(type);
        } else if (type.equals(Type.Kind.ARRAY)) {
            putArray(type);
        } else if (type.equals(Type.Kind.PRIMITIVE)) {
            putPrimitive(type);
        } else if (type.equals(Type.Kind.VOID)) {
            putVoid();
        } else if (type.equals(Type.Kind.METHOD)) {
            putMethod(type);
        } else if (type.equals(Type.Kind.INTERFACE)) {
            putInterface(type);
        } else {
            throw new IllegalArgumentException("Unsupported type at index " + i);
        }
    }
}

