protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Type parameter cannot be null");
    }
    if (value == null) {
        throw new IllegalArgumentException("Value parameter cannot be null");
    }
    if (!(value instanceof Character)) {
        throw new IllegalArgumentException("Value parameter must be of type Character");
    }
    Character character = (Character) value;
    if (type == Character.class) {
        return character;
    } else if (type == Character.Type.class) {
        return character.getType();
    } else if (type == Character.SubType.class) {
        return character.getSubType();
    } else if (type == Character.Area.class) {
        return character.getArea();
    } else {
        throw new IllegalArgumentException("Unsupported type");
    }
}

