public static int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 0) {
    throw new IllegalArgumentException("Desired capacity cannot be negative");
  }

  if (desiredCapacity < 2) {
    return 2;
  }

  if (desiredCapacity < 3) {
    return 3;
  }

  int prime = 5;
  while (true) {
    if (isPrime(prime)) {
      return prime;
    }

    prime += 2;
  }
}

