public final byte[] toByteArray() {
  if (buffers.isEmpty()) {
    return new byte[0];
  } else {
    int totalSize = 0;
    for (ByteBuffer buffer : buffers) {
      totalSize += buffer.remaining();
    }

    byte[] result = new byte[totalSize];
    int index = 0;
    for (ByteBuffer buffer : buffers) {
      int remaining = buffer.remaining();
      buffer.get(result, index, remaining);
      index += remaining;
    }

    return result;
  }
}

public static String unescapeJava(String str) {

// Handle null string input
if (str == null) {
return null;
}

// Replace all occurrences of '\\' with '\'
str = str.replaceAll("\\\\", "\\");

// Replace all occurrences of '\n' with newline character
str = str.replaceAll("\\n", "\n");

// Replace all occurrences of '\t' with tab character
str = str.replaceAll("\\t", "\t");

// Replace all occurrences of '\b' with backspace character
str = str.replaceAll("\\b", "\b");

// Replace all occurrences of '\f' with form feed character
str = str.replaceAll("\\f", "\f");

// Replace all occurrences of '\r' with carriage return character
str = str.replaceAll("\\r", "\r");

// Remove all occurrences of '\\' at the end of a string
str = str.replaceAll("\\\\$", "");

return str;
}

