public String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Validate the input
    if(constantPoolEntryIndex < 0 || constantPoolIndex >= this.constantPool().size()) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    if (charBuffer == null || charBuffer.length == 0) {
        throw new IllegalArgumentException("Invalid buffer");
    }

    // Read the CONSTANT_Utf8 entry from the class file
    ConstantUtf8 constantUtf8 = (ConstantUtf8) this.constantPool().get(constantPoolEntryIndex);
    String string = constantUtf8.getString();

    if (string == null) {
        throw new IllegalArgumentException("Cannot read string from CONSTANT_Utf8 entry");
    }

    // Copy the string to the provided buffer
    charBuffer = new char[string.length()];
    string.getChars(0, string.length(), charBuffer, 0);

    return charBuffer;
}

