protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Validate input parameters
    Objects.requireNonNull(tour, "The tour set must not be null");
    Objects.requireNonNull(graph, "The graph must not be null");

    // Create a list of vertices from the tour set
    List<V> vertices = new ArrayList<>();
    for (E edge : tour) {
        vertices.add(graph.getEdgeSource(edge));
        vertices.add(graph.getEdgeTarget(edge));
    }

    // Create a path from the vertices
    GraphPath<V,E> path = new GraphPath<>(vertices, new DefaultWeight(0.0));

    // Add the edges to the path
    for (E edge : tour) {
        path.addEdge(edge, graph.getEdgeWeight(edge));
    }

    return path;
}

