private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i < input.length() - 1) {
            char nextChar = input.charAt(i + 1);
            if (nextChar == 'n') {
                output.append('\n');
            } else if (nextChar == 't') {
                output.append('\t');
            } else if (nextChar == 'b') {
                output.append('\b');
            } else if (nextChar == 'f') {
                output.append('\f');
            } else if (nextChar == 'r') {
                output.append('\r');
            } else if (nextChar == '"') {
                output.append('"');
            } else if (nextChar == '\'') {
                output.append('\'');
            } else if (nextChar == '\\') {
                output.append('\\');
            } else {
                output.append(c);
            }
            i++;
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

