private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if the minimum label is valid
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid minimum label: " + minLabel);
    }

    // Find the non-empty bucket with the minimum label
    int nonEmptyIdx = -1;
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (!bucketsByLabel.get(i).isEmpty() && labels.get(i) == minLabel) {
            nonEmptyIdx = i;
            break;
        }
    }

    // If the non-empty bucket is not found, do nothing
    if (nonEmptyIdx == -1) {
        return;
    }

    // Move all vertices from the non-empty bucket to the bucket with label 0
    Set<Integer> nonEmptyBucket = bucketsByLabel.get(nonEmptyIdx);
    Set<Integer> bucket0 = bucketsByLabel.get(0);
    for (Integer vertex : nonEmptyBucket) {
        labels.set(vertex, 0);
        bucket0.add(vertex);
    }
    nonEmptyBucket.clear();

    // Update the labeling
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        if (i == 0) {
            bucket.clear();
        } else if (labels.get(i) <= minLabel) {
            bucket.addAll(bucket0);
        }
    }
}

