public String parseToken(final char[] terminators) {
    // Define the token as a StringBuilder to allow for efficient appending
    StringBuilder token = new StringBuilder();

    // Loop through the characters in the input stream
    while (this.pos < this.input.length()) {
        // Get the current character
        char currentChar = this.input.charAt(this.pos);

        // Check if the current character is a terminator
        for (char terminator : terminators) {
            if (currentChar == terminator) {
                // If it is a terminator, return the token
                return token.toString();
            }
        }

        // If the current character is not a terminator, append it to the token
        token.append(currentChar);
        this.pos++;
    }

    // If we reach the end of the input without encountering a terminator, return the token
    return token.toString();
}

