private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds.isEmpty()) {
        throw new IllegalArgumentException("bounds must not be empty");
    }
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long sum = 0;
    for (int i = 0; i < bounds.size(); i++) {
        int bound = bounds.get(i);
        if (bound <= 0) {
            throw new IllegalArgumentException("bounds must not be negative or zero");
        }
        sum += bound;
        suffixSum.add(sum);
    }
    return Pair.of(suffixSum, sum);
}

public static void reverse(Object[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || from >= arr.length || to < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid input");
    }
    int left = from;
    int right = to;
    while (left < right) {
        Object temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

