public static String base64Decode(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string must not be null");
    }
    if (!s.matches("^[A-Za-z0-9+/]*$")) {
        throw new IllegalArgumentException("Input string must be a valid Base64 encoded string");
    }
    byte[] data = s.getBytes();
    int dataLength = data.length;
    if (dataLength % 4 != 0) {
        throw new IllegalArgumentException("Input string must be a multiple of 4 bytes");
    }
    byte[] output = new byte[dataLength];
    for (int i = 0; i < dataLength; i += 4) {
        int a = data[i] & 0xFF;
        int b = data[i + 1] & 0xFF;
        int c = data[i + 2] & 0xFF;
        int d = data[i + 3] & 0xFF;
        output[i / 4] = (byte) ((a << 2) | (b >> 4));
        output[i / 4 + 1] = (byte) ((b << 4) | (c >> 2));
        output[i / 4 + 2] = (byte) ((c << 6) | (d >> 0));
    }
    return new String(output);
}

