public ByteVector putInt(final int intValue) {
  if (intValue < 0) {
    throw new IllegalArgumentException("intValue must be non-negative");
  }
  // Calculate the number of bytes needed to represent the int
  int numBytes = (int) Math.ceil(intValue / 256.0);

  if (numBytes > 4) {
    throw new IllegalArgumentException("intValue is too large to be represented by a 4-byte integer");
  }

  // Enlarge the byte vector if necessary
  if (numBytes > this.buffer.length - this.position) {
    byte[] newBuffer = new byte[this.buffer.length + numBytes];
    System.arraycopy(this.buffer, 0, newBuffer, 0, this.buffer.length);
    this.buffer = newBuffer;
  }

  // Put the int into the byte vector
  for (int i = 0; i < numBytes; i++) {
    int byteValue = intValue % 256;
    this.buffer[this.position++] = (byte) byteValue;
    intValue = intValue / 256;
  }

  return this;
}

