public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException(" buf is null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart is less than 0");
    }
    if (nameStart > buf.length()) {
        throw new IndexOutOfBoundsException("nameStart is greater than buf.length()");
    }
    char[] ch = buf.toString().substring(nameStart).toCharArray();
    String abbr = "";
    for (int i = 0; i < ch.length; i++) {
        if (ch[i] == ' ') {
            abbr += ch[i + 1];
        } else {
            abbr += ch[i];
        }
    }
    buf.setLength(nameStart);
    buf.append(abbr);
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
  if (typeVariable == null) {
    throw new IllegalArgumentException("TypeVariable cannot be null");
  }

  Type[] bounds = typeVariable.getBounds();
  if (bounds.length == 0) {
    return Object.class;
  }

  // If the type variable has a single bound that is not a wildcard,
  // we can simply return that bound.
  if (bounds.length == 1 && !(bounds[0] instanceof WildcardType)) {
    return bounds[0];
  }

  // If the type variable has multiple bounds, we need to consider
  // the intersection of all of them.
  List<Type> upperBounds = new ArrayList<>();
  for (Type bound : bounds) {
    if (bound instanceof WildcardType) {
      // If the bound is a wildcard, we need to extract the upper bound.
      upperBounds.add(((WildcardType) bound).getUpperBounds());
    } else {
      // Otherwise, we can just add the bound directly.
      upperBounds.add(bound);
    }
  }

  // We can use a useful type- util method to get the intersection of all the bounds.
  Type intersection = TypeUtils.getIntersectionType(upperBounds.toArray(new Type[0]));

  // If the intersection is Object.class, we can return that directly.
  if (intersection.equals(Object.class)) {
    return Object.class;
  }

  // If the intersection is a wildcard type, we need to extract the upper bound.
  if (intersection instanceof WildcardType) {
    return ((WildcardType) intersection).getUpperBounds()[0];
  }

  // Otherwise, we can just return the intersection.
  return intersection;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the subgraph is a clique by checking if every vertex is connected to every other vertex in the subgraph
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
  // Initialize a list to store the lower bounds for each key
  List<Integer> lowerBounds = new ArrayList<>();

  // Iterate over each key and compute its lower bound
  for (K key : keys) {
    int lowerBound = Collections.min(keys, new Comparator<K>() {
      @Override
      public int compare(K k1, K k2) {
        if (k1.compareTo(k2) < 0) {
          return -1;
        } else if (k1.compareTo(k2) > 0) {
          return 1;
        } else {
          return 0;
        }
      }
    });
    lowerBounds.add(lowerBound);
  }

  return lowerBounds;
}

public void pop(String descriptor) throws RuntimeException {
    int numTypes = descriptor.length();
    for (int i = 0; i < numTypes; i++) {
        char ch = descriptor.charAt(i);
        if (ch == '(') {
            // Found an argument type, pop it from the output frame stack
            popType();
            // If the next character is not ')', then there are more argument types
            if (descriptor.charAt(i + 1) != ')') {
                i++;
            }
        } else if (ch == ')') {
            // Found a return type, pop it from the output frame stack
            popType();
        } else {
            throw new RuntimeException("Invalid descriptor: " + descriptor);
        }
    }
}

