private List<Integer> computeUpperBounds(List<K> keys) {
    // Check if the input list is null or empty
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("The input list is null or empty");
    }

    // Initialize the result list and sort the input list
    List<Integer> result = new ArrayList<>();
    Collections.sort(keys);

    // Iterate over the input list and find the minimum lower bound for each key
    for (int i = 0; i < keys.size(); i++) {
        int min = keys.get(i);
        for (int j = i + 1; j < keys.size(); j++) {
            if (keys.get(j) < min) {
                min = keys.get(j);
            }
        }
        result.add(min);
    }

    return result;
}

