public boolean isExpired(long timestamp, long expiredThreshold) {
    // Handle null or invalid input
    if (timestamp <= 0 || expiredThreshold <= 0) {
        throw new IllegalArgumentException("Invalid input: timestamp and expiredThreshold must be positive numbers");
    }

    long currentTime = System.currentTimeMillis();
    long lastUpdatedTime = currentTime - timestamp;
    long timeElapsed = lastUpdatedTime - expiredThreshold;

    // Check if the metric is expired
    if (timeElapsed >= 0) {
        return true;
    } else {
        return false;
    }
}

